{
  "name": "json-alexander",
  "version": "1.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "npm run build && ENTRY=content vite build --watch",
    "build": "ENTRY=content vite build && ENTRY=page-script vite build",
    "zip": "npm run build && cd dist && zip -r ../json-alexander.zip . && cd .."
  },
  "devDependencies": {
    "@types/chrome": "^0.1.39",
    "@types/node": "^25.5.2",
    "typescript": "^5.8.0",
    "vite": "^6.2.0",
    "vite-plugin-static-copy": "^3.0.0"
  }
}

import { defineConfig } from "vite";
import { viteStaticCopy } from "vite-plugin-static-copy";
import { resolve } from "path";

const entry = process.env.ENTRY || "content";

export default defineConfig({
  build: {
    outDir: "dist",
    emptyOutDir: entry === "content",
    lib: {
      entry: resolve(__dirname, `src/${entry}.ts`),
      name: entry.replace(/-/g, "_"),
      formats: ["iife"],
      fileName: () => `${entry}.js`,
    },
    rollupOptions: {
      output: {
        assetFileNames: "content.[ext]",
      },
    },
  },
  plugins: [
    ...(entry === "content"
      ? [
          viteStaticCopy({
            targets: [
              { src: "manifest.json", dest: "." },
              { src: "icons/*", dest: "icons" },
              { src: "src/pointer-32.png", dest: "." },
            ],
          }),
        ]
      : []),
  ],
});

